CREATE TABLE IF NOT EXISTS `coa_dungeon_rescale_loot` (
    `map_id` SMALLINT UNSIGNED NOT NULL,
    `difficulty` TINYINT UNSIGNED NOT NULL,
    `source_item` INT UNSIGNED NOT NULL,
    `target_item` INT UNSIGNED NOT NULL,
    PRIMARY KEY (`map_id`, `difficulty`, `source_item`)
) ENGINE=InnoDB;

DELETE FROM `coa_dungeon_rescale_loot` WHERE `map_id` IN (540, 542, 543);

UPDATE `creature` SET `spawnMask` = `spawnMask` | 4 WHERE `map` IN (540, 542, 543) AND (`spawnMask` & 2) <> 0;
UPDATE `gameobject` SET `spawnMask` = `spawnMask` | 4 WHERE `map` IN (540, 542, 543) AND (`spawnMask` & 2) <> 0;
